"""Theme shell, migration backup/rejected records, old/new file roundtrip and large-score behavior."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',required=True,type=Path);p.add_argument('--url');a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1375,'height':884},reduced_motion='no-preference');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));url=a.url or (root/'SkyMusicStudio_Standalone.html').as_uri();page.goto(url);page.locator('.card-play').first.click();page.wait_for_function('!document.getElementById("songEntryTransition").hidden===false');assert page.locator('#playerView').is_visible();assert page.locator('#musicWorkbench').is_hidden();assert not page.locator('#playerView').evaluate('e=>e.inert')
 page.evaluate('window.__SKY_STUDIO_TEST__.goHome()');page.wait_for_function('document.getElementById("homeView").hidden===false && document.getElementById("songEntryTransition").hidden');assert page.locator('#musicWorkbench').is_hidden()
 for theme in ['christmas','starlight','citylights','prairie','rainforest','vault']:
  page.evaluate('''id=>{const t=window.__SKY_STUDIO_TEST__,p=t.state.library.find(p=>p.theme.id===id);t.openSong(p.id)}''',theme);page.locator('#scoreEditorBtn').click();assert page.locator('#musicWorkbench').get_attribute('data-theme')==theme
  styles=page.locator('#musicWorkbench').evaluate('e=>{const s=getComputedStyle(e);return {text:s.color,surface:s.getPropertyValue("--player-surface-end"),image:s.getPropertyValue("--music-scene")}}');assert styles['surface'] and styles['image'].startswith('url(')
  page.locator('[data-bottom=rhythm]').click();assert page.locator('#musicRhythmGrid button').count()==32;page.locator('[data-music-action=keymap]').click();assert page.locator('#musicDialog').get_attribute('data-theme')==theme;page.keyboard.press('Escape');page.screenshot(path=str(a.output/(theme+'.png')));page.locator('#musicEdit').click();page.locator('#discardChanges').click()
 page.locator('#scoreEditorBtn').click()
 # A large score remains bounded in DOM/canvas size; pure timing and rendering do not lose notes.
 perf=page.evaluate('''()=>{const w=window.SKY_MUSIC_TEST,M=w.Music,c=M.blank(),track=c.tracks[0].id;c.notes=Array.from({length:20000},(_,i)=>({id:'n'+i,trackId:track,pitch:21+i%88,startTick:i*120,durationTicks:90,soundTicks:80,gate:80/90,velocity:85}));c.lengthTicks=2400000;const begin=performance.now();w.mw.project={...w.mw.project,composition:M.validate(c)};w.mw.track=track;w.musicRender();return {ms:performance.now()-begin,count:w.mw.project.composition.notes.length,canvas:document.getElementById('musicCanvas').width,viewport:document.getElementById('musicRollViewport').clientWidth}}''');assert perf['count']==20000 and perf['canvas']<=perf['viewport']*2+2 and perf['ms']<3000,perf
 # Preserve old raw library before first v2 persistence, retain rejected records verbatim.
 legacy=page.evaluate('window.__SKY_STUDIO_TEST__.state.library.find(p=>p.originKind==="builtin")');legacy.pop('composition',None);legacy['id']='migration-source';legacy['originKind']='user';broken={'id':'unreadable-record','composition':{'format':'skytrack','schemaVersion':2,'ppq':960,'tracks':[]},'opaque':'keep me'};raw=json.dumps([legacy,broken],ensure_ascii=False)
 page.evaluate('(raw)=>{localStorage.setItem("sky-studio-projects-v03",raw);localStorage.removeItem("sky-studio-projects-v03-backup-musical-v2")}',raw);page.reload();page.evaluate('''()=>{const t=window.__SKY_STUDIO_TEST__,p=t.state.library.find(p=>p.id==='migration-source');window.SKY_MUSIC_TEST.Music.ensure(p);window.SKY_MUSIC_TEST.musicPersist(t.state.library)}''');assert page.evaluate('localStorage.getItem("sky-studio-projects-v03-backup-musical-v2")')==raw
 saved=page.evaluate('JSON.parse(localStorage.getItem("sky-studio-projects-v03"))');assert next(p for p in saved if p['id']=='unreadable-record')==broken;assert next(p for p in saved if p['id']=='migration-source')['composition']['schemaVersion']==2
 # Corrupt JSON blocks write without replacing the original bytes.
 page.evaluate('localStorage.setItem("sky-studio-projects-v03","broken raw json")');page.reload();blocked=page.evaluate('''()=>{try{window.SKY_MUSIC_TEST.musicPersist(window.__SKY_STUDIO_TEST__.state.library);return false}catch(e){return true}}''');assert blocked and page.evaluate('localStorage.getItem("sky-studio-projects-v03")')=='broken raw json'
 assert not errors,errors;b.close()
(a.output/'results.json').write_text(json.dumps({'passed':True,'themes':6,'performance':perf,'migrationBackup':True,'rejectedRecordsPreserved':True,'corruptStorageBlocked':True,'errors':errors},indent=2),'utf-8');print('PASS transition, six themes, large score, migration backup and corrupt-record protection')
